arguments.cmd:
apply_patch <<'PATCH'
*** Begin Patch
*** Add File: output/styles.css
+:root{
+  --bg: #fbfaf7;
+  --surface: #ffffff;
+  --surface-2: #f6f3ec;
+  --text: #142015;
+  --muted: #546058;
+  --border: rgba(20, 32, 21, 0.12);
+  --shadow: 0 10px 30px rgba(20, 32, 21, 0.10);
+  --shadow-sm: 0 6px 18px rgba(20, 32, 21, 0.10);
+
+  --primary: #00824A;
+  --primary-2: #2cb66f;
+  --forest: #32462F;
+  --cream: #F3CEA1;
+  --coffee: #4c2f24;
+
+  --radius-xl: 22px;
+  --radius-lg: 18px;
+  --radius-md: 14px;
+  --radius-sm: 12px;
+
+  --container: 1160px;
+  --gutter: 20px;
+
+  --ring: 0 0 0 4px rgba(0,130,74,0.18);
+  --focus: 0 0 0 4px rgba(0,130,74,0.20), 0 0 0 1px rgba(0,130,74,0.35) inset;
+
+  --ease: cubic-bezier(.2,.8,.2,1);
+  --dur: 220ms;
+}
+
+*{box-sizing:border-box}
+html,body{height:100%}
+body{
+  margin:0;
+  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
+  color:var(--text);
+  background:
+    radial-gradient(1200px 700px at 10% -10%, rgba(243,206,161,0.55), transparent 55%),
+    radial-gradient(1000px 600px at 95% 0%, rgba(0,130,74,0.16), transparent 55%),
+    linear-gradient(180deg, #ffffff, var(--bg));
+  line-height:1.55;
+}
+
+img{max-width:100%; display:block}
+a{color:inherit; text-decoration:none}
+button,input,select{font:inherit}
+
+.skip-link{
+  position:absolute;
+  left:-999px;
+  top:10px;
+  background:var(--surface);
+  border:1px solid var(--border);
+  padding:10px 14px;
+  border-radius:12px;
+  z-index:9999;
+}
+.skip-link:focus{left:10px; box-shadow:var(--focus)}
+
+.container{max-width:var(--container); margin:0 auto; padding:0 var(--gutter)}
+.section{padding:56px 0}
+.section.tight{padding:36px 0}
+.grid{display:grid; gap:18px}
+
+.eyebrow{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  font-weight:600;
+  font-size:13px;
+  color:var(--forest);
+  background:rgba(0,130,74,0.08);
+  border:1px solid rgba(0,130,74,0.18);
+  padding:6px 10px;
+  border-radius:999px;
+}
+
+.h1,.h2,.h3{font-family: "DM Sans", Inter, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif; letter-spacing:-0.02em}
+.h1{font-size:44px; line-height:1.08; margin:10px 0 10px}
+.h2{font-size:32px; line-height:1.12; margin:0 0 10px}
+.h3{font-size:20px; line-height:1.25; margin:0 0 6px}
+.p{margin:0; color:var(--muted)}
+.muted{color:var(--muted)}
+
+.card{
+  background:var(--surface);
+  border:1px solid var(--border);
+  border-radius:var(--radius-xl);
+  box-shadow:var(--shadow);
+}
+.card.pad{padding:20px}
+.card.soft{background:linear-gradient(180deg, rgba(255,255,255,0.88), rgba(255,255,255,0.70))}
+
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap:10px;
+  min-height:44px;
+  padding:12px 16px;
+  border-radius:999px;
+  border:1px solid transparent;
+  font-weight:650;
+  cursor:pointer;
+  transition: transform var(--dur) var(--ease), box-shadow var(--dur) var(--ease), background var(--dur) var(--ease), border-color var(--dur) var(--ease);
+  user-select:none;
+}
+.btn:active{transform:translateY(1px)}
+.btn:focus-visible{outline:none; box-shadow:var(--focus)}
+
+.btn.primary{
+  background:linear-gradient(180deg, var(--primary-2), var(--primary));
+  color:white;
+  box-shadow:0 10px 22px rgba(0,130,74,0.25);
+}
+.btn.primary:hover{box-shadow:0 14px 28px rgba(0,130,74,0.30)}
+
+.btn.ghost{
+  background:rgba(255,255,255,0.8);
+  border-color:rgba(20,32,21,0.14);
+}
+.btn.ghost:hover{border-color:rgba(20,32,21,0.22); box-shadow:var(--shadow-sm)}
+
+.btn.link{
+  background:transparent;
+  border-color:transparent;
+  padding:10px 10px;
+  border-radius:12px;
+  color:var(--forest);
+}
+.btn.link:hover{background:rgba(0,130,74,0.08)}
+
+.chip{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  border:1px solid var(--border);
+  background:rgba(255,255,255,0.75);
+  border-radius:999px;
+  padding:8px 12px;
+  min-height:44px;
+}
+
+.tag{
+  font-size:12px;
+  font-weight:650;
+  color:var(--forest);
+  background:rgba(243,206,161,0.55);
+  border:1px solid rgba(76,47,36,0.12);
+  padding:6px 10px;
+  border-radius:999px;
+}
+
+.nav{
+  position:sticky;
+  top:0;
+  z-index:1000;
+  backdrop-filter:saturate(160%) blur(10px);
+  background:rgba(251, 250, 247, 0.72);
+  border-bottom:1px solid rgba(20,32,21,0.10);
+}
+.nav-inner{display:flex; align-items:center; justify-content:space-between; padding:14px 0; gap:14px}
+
+.brand{display:flex; align-items:center; gap:10px; min-width:190px}
+.logo{
+  width:38px; height:38px; border-radius:14px;
+  background: radial-gradient(12px 12px at 30% 30%, rgba(255,255,255,0.75), rgba(255,255,255,0) 55%),
+              linear-gradient(180deg, var(--primary-2), var(--primary));
+  box-shadow:0 12px 22px rgba(0,130,74,0.22);
+  position:relative;
+}
+.logo:after{
+  content:"";
+  position:absolute;
+  left:10px; top:9px;
+  width:18px; height:18px;
+  border-radius:9px 9px 11px 11px;
+  background:rgba(255,255,255,0.90);
+  transform:rotate(-18deg);
+  clip-path: polygon(30% 0%, 65% 0%, 100% 35%, 70% 100%, 35% 100%, 0% 40%);
+}
+.brand strong{font-family:"DM Sans", Inter, sans-serif; font-size:16px; letter-spacing:-0.02em}
+.brand span{display:block; font-size:12px; color:var(--muted)}
+
+.nav-links{display:flex; align-items:center; gap:4px; flex-wrap:wrap}
+.nav-links a{
+  padding:10px 12px;
+  border-radius:999px;
+  color:var(--forest);
+  font-weight:650;
+  border:1px solid transparent;
+  transition: background var(--dur) var(--ease), border-color var(--dur) var(--ease);
+}
+.nav-links a:hover{background:rgba(0,130,74,0.08); border-color:rgba(0,130,74,0.16)}
+.nav-links a[aria-current="page"]{background:rgba(0,130,74,0.10); border-color:rgba(0,130,74,0.20)}
+
+.nav-actions{display:flex; align-items:center; gap:10px}
+.nav-actions .sep{width:1px; height:26px; background:rgba(20,32,21,0.14)}
+
+.mobile-toggle{display:none}
+
+.hero{
+  padding:34px 0 18px;
+}
+.hero-grid{
+  display:grid;
+  grid-template-columns: 1.2fr 0.8fr;
+  gap:18px;
+  align-items:stretch;
+}
+.hero-card{padding:26px; border-radius:var(--radius-xl); overflow:hidden; position:relative}
+.hero-card:before{
+  content:"";
+  position:absolute; inset:-1px;
+  background:
+    radial-gradient(520px 260px at 20% 10%, rgba(243,206,161,0.75), transparent 60%),
+    radial-gradient(480px 240px at 80% 0%, rgba(0,130,74,0.22), transparent 58%),
+    linear-gradient(180deg, rgba(255,255,255,0.92), rgba(255,255,255,0.72));
+  z-index:0;
+}
+.hero-card > *{position:relative; z-index:1}
+.hero-actions{display:flex; gap:12px; flex-wrap:wrap; margin-top:16px}
+
+.photo{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(20,32,21,0.12);
+  box-shadow:var(--shadow);
+  overflow:hidden;
+  min-height:260px;
+  background:
+    radial-gradient(420px 240px at 25% 25%, rgba(243,206,161,0.65), transparent 60%),
+    radial-gradient(360px 220px at 75% 30%, rgba(0,130,74,0.20), transparent 60%),
+    linear-gradient(135deg, rgba(255,255,255,0.85), rgba(246,243,236,0.85));
+  position:relative;
+}
+.photo .caption{
+  position:absolute;
+  left:16px;
+  bottom:16px;
+  right:16px;
+  padding:10px 12px;
+  border-radius:14px;
+  background:rgba(255,255,255,0.85);
+  border:1px solid rgba(20,32,21,0.10);
+  color:var(--muted);
+  font-size:13px;
+}
+
+.feature-grid{display:grid; grid-template-columns: 1fr 1fr; gap:18px}
+.feature{
+  padding:20px;
+  display:grid;
+  gap:12px;
+}
+.feature .meta{display:flex; align-items:center; justify-content:space-between; gap:12px}
+.feature .meta .tag{white-space:nowrap}
+.feature .icon{
+  width:42px; height:42px;
+  border-radius:16px;
+  background:rgba(0,130,74,0.10);
+  border:1px solid rgba(0,130,74,0.18);
+  display:grid;
+  place-items:center;
+}
+
+.icon svg{width:22px; height:22px; color:var(--primary)}
+
+.pillrow{display:flex; flex-wrap:wrap; gap:10px; margin-top:14px}
+
+.breadcrumb{font-size:13px; color:var(--muted)}
+.breadcrumb a{color:var(--forest)}
+.breadcrumb a:hover{text-decoration:underline}
+
+.two-col{display:grid; grid-template-columns: 320px 1fr; gap:18px; align-items:start}
+.sidebar{padding:16px}
+.sidebar h3{margin:0 0 10px}
+.sidebar .group{margin-top:14px}
+.sidebar .group-title{font-weight:750; color:var(--forest); font-size:13px; letter-spacing:0.01em; text-transform:uppercase; margin:0 0 6px}
+.side-links{display:grid; gap:4px}
+.side-links a{padding:10px 10px; border-radius:12px; color:var(--forest); font-weight:600; border:1px solid transparent}
+.side-links a:hover{background:rgba(0,130,74,0.08); border-color:rgba(0,130,74,0.16)}
+.side-links a.active{background:rgba(0,130,74,0.10); border-color:rgba(0,130,74,0.20)}
+
+.menu-content{padding:16px}
+.menu-panels{display:grid; gap:12px}
+.panel{
+  padding:16px;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(20,32,21,0.12);
+  background:linear-gradient(180deg, rgba(255,255,255,0.92), rgba(255,255,255,0.70));
+}
+.items{display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap:12px; margin-top:12px}
+.item{
+  border-radius:16px;
+  border:1px solid rgba(20,32,21,0.10);
+  background:rgba(246,243,236,0.75);
+  padding:12px;
+}
+.item strong{display:block; font-size:14px}
+.item span{display:block; font-size:12px; color:var(--muted)}
+
+.tabs{display:flex; gap:8px; flex-wrap:wrap}
+.tab{
+  border:1px solid rgba(20,32,21,0.14);
+  background:rgba(255,255,255,0.80);
+  border-radius:999px;
+  padding:10px 12px;
+  min-height:44px;
+  font-weight:700;
+  color:var(--forest);
+  cursor:pointer;
+  transition: background var(--dur) var(--ease), border-color var(--dur) var(--ease), transform var(--dur) var(--ease);
+}
+.tab:focus-visible{outline:none; box-shadow:var(--focus)}
+.tab:hover{background:rgba(0,130,74,0.08); border-color:rgba(0,130,74,0.20)}
+.tab[aria-selected="true"]{background:rgba(0,130,74,0.12); border-color:rgba(0,130,74,0.28)}
+
+.tab-panel{
+  margin-top:14px;
+  padding:18px;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(20,32,21,0.12);
+  background:linear-gradient(180deg, rgba(255,255,255,0.95), rgba(246,243,236,0.78));
+  box-shadow:var(--shadow-sm);
+}
+.tab-panel[hidden]{display:none}
+
+.tier-grid{display:grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap:14px}
+.tier{padding:16px}
+.tier .tier-head{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-bottom:10px}
+.badge{
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+  padding:6px 10px;
+  border-radius:999px;
+  background:rgba(243,206,161,0.55);
+  border:1px solid rgba(76,47,36,0.12);
+  font-weight:750;
+  font-size:12px;
+  color:var(--coffee);
+}
+.list{margin:10px 0 0; padding-left:18px; color:var(--muted)}
+.list li{margin:6px 0}
+
+.carousel{
+  position:relative;
+  overflow:hidden;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(20,32,21,0.12);
+  background:rgba(255,255,255,0.72);
+}
+.carousel-track{
+  display:flex;
+  gap:12px;
+  padding:14px;
+  scroll-behavior:smooth;
+  overflow:auto;
+  scrollbar-width:none;
+}
+.carousel-track::-webkit-scrollbar{display:none}
+.gift-card{
+  flex:0 0 240px;
+  border-radius:18px;
+  border:1px solid rgba(20,32,21,0.10);
+  background:linear-gradient(135deg, rgba(243,206,161,0.75), rgba(0,130,74,0.18));
+  box-shadow:0 10px 18px rgba(20,32,21,0.10);
+  overflow:hidden;
+  position:relative;
+  min-height:150px;
+}
+.gift-card .label{position:absolute; left:14px; bottom:14px; right:14px; padding:10px 12px; border-radius:14px; background:rgba(255,255,255,0.85); border:1px solid rgba(20,32,21,0.10); font-weight:750}
+.gift-card .sub{display:block; font-size:12px; font-weight:650; color:var(--muted); margin-top:2px}
+
+.carousel-btn{
+  position:absolute;
+  top:50%;
+  transform:translateY(-50%);
+  width:44px; height:44px;
+  border-radius:999px;
+  border:1px solid rgba(20,32,21,0.14);
+  background:rgba(255,255,255,0.90);
+  display:grid;
+  place-items:center;
+  cursor:pointer;
+  transition: transform var(--dur) var(--ease), box-shadow var(--dur) var(--ease), background var(--dur) var(--ease);
+}
+.carousel-btn:hover{box-shadow:var(--shadow-sm)}
+.carousel-btn:active{transform:translateY(-50%) scale(0.98)}
+.carousel-btn:focus-visible{outline:none; box-shadow:var(--focus)}
+.carousel-btn.prev{left:10px}
+.carousel-btn.next{right:10px}
+.carousel-btn svg{width:18px; height:18px; color:var(--forest)}
+
+.locator{
+  display:grid;
+  grid-template-columns: 420px 1fr;
+  gap:18px;
+  align-items:start;
+}
+.search-card{padding:16px}
+.field{display:grid; gap:8px}
+.label{font-weight:750; font-size:13px; color:var(--forest)}
+.input{
+  min-height:44px;
+  padding:12px 12px;
+  border-radius:14px;
+  border:1px solid rgba(20,32,21,0.16);
+  background:rgba(255,255,255,0.92);
+}
+.input:focus{outline:none; box-shadow:var(--focus); border-color:rgba(0,130,74,0.25)}
+.suggestions{margin-top:10px; border:1px solid rgba(20,32,21,0.12); border-radius:14px; background:rgba(255,255,255,0.95); overflow:hidden}
+.suggestions[hidden]{display:none}
+.suggestions button{width:100%; text-align:left; padding:12px 12px; border:0; background:transparent; cursor:pointer}
+.suggestions button:hover{background:rgba(0,130,74,0.08)}
+.toggle{
+  display:flex;
+  gap:8px;
+  padding:6px;
+  border-radius:999px;
+  border:1px solid rgba(20,32,21,0.12);
+  background:rgba(255,255,255,0.72);
+}
+.toggle button{
+  flex:1;
+  min-height:44px;
+  border-radius:999px;
+  border:0;
+  background:transparent;
+  font-weight:750;
+  color:var(--forest);
+  cursor:pointer;
+}
+.toggle button[aria-pressed="true"]{background:rgba(0,130,74,0.12)}
+.filters{margin-top:12px; display:grid; gap:10px}
+.filters[hidden]{display:none}
+.check{
+  display:flex;
+  align-items:center;
+  gap:10px;
+  padding:10px 12px;
+  border-radius:14px;
+  border:1px solid rgba(20,32,21,0.12);
+  background:rgba(246,243,236,0.78);
+}
+.check input{width:18px; height:18px}
+
+.map{
+  min-height:420px;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(20,32,21,0.12);
+  background:
+    radial-gradient(420px 260px at 25% 30%, rgba(0,130,74,0.18), transparent 60%),
+    radial-gradient(420px 260px at 75% 70%, rgba(243,206,161,0.55), transparent 65%),
+    linear-gradient(135deg, rgba(255,255,255,0.92), rgba(246,243,236,0.85));
+  position:relative;
+  overflow:hidden;
+  box-shadow:var(--shadow);
+}
+.pin{position:absolute; width:14px; height:14px; border-radius:999px; background:var(--primary); box-shadow:0 0 0 5px rgba(0,130,74,0.18)}
+.map .note{position:absolute; left:16px; bottom:16px; right:16px; padding:10px 12px; border-radius:14px; background:rgba(255,255,255,0.85); border:1px solid rgba(20,32,21,0.10); color:var(--muted); font-size:13px}
+
+.results{display:grid; gap:10px}
+.store{
+  padding:14px;
+  border-radius:18px;
+  border:1px solid rgba(20,32,21,0.12);
+  background:rgba(255,255,255,0.86);
+  box-shadow:var(--shadow-sm);
+}
+.store .top{display:flex; align-items:flex-start; justify-content:space-between; gap:12px}
+.store h3{margin:0; font-size:16px; font-family:"DM Sans", Inter, sans-serif}
+.store .meta{font-size:13px; color:var(--muted); margin-top:4px}
+.store .features{display:flex; flex-wrap:wrap; gap:8px; margin-top:10px}
+
+.footer{
+  margin-top:42px;
+  padding:40px 0 20px;
+  border-top:1px solid rgba(20,32,21,0.10);
+  background:linear-gradient(180deg, rgba(246,243,236,0.65), rgba(251,250,247,0.92));
+}
+.footer-grid{display:grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap:14px}
+.footer h3{font-family:"DM Sans", Inter, sans-serif; font-size:14px; margin:0 0 10px}
+.footer a{display:block; padding:8px 0; color:var(--muted)}
+.footer a:hover{color:var(--forest); text-decoration:underline}
+.footer-bottom{display:flex; align-items:center; justify-content:space-between; gap:12px; flex-wrap:wrap; margin-top:18px; color:var(--muted); font-size:13px}
+
+.footer-section{border:1px solid transparent; border-radius:14px; padding:10px}
+.footer-section button{
+  display:none;
+  width:100%;
+  align-items:center;
+  justify-content:space-between;
+  gap:10px;
+  background:transparent;
+  border:0;
+  padding:0;
+  cursor:pointer;
+  color:var(--forest);
+  font-weight:800;
+  font-size:14px;
+}
+.footer-section button:focus-visible{outline:none; box-shadow:var(--focus); border-radius:12px}
+.footer-links{display:block}
+
+.cookie{
+  position:fixed;
+  left:14px;
+  right:14px;
+  bottom:14px;
+  z-index:2000;
+}
+.cookie .card{padding:16px; display:flex; align-items:flex-start; justify-content:space-between; gap:14px}
+.cookie h3{margin:0 0 6px; font-family:"DM Sans", Inter, sans-serif}
+.cookie p{margin:0; color:var(--muted); font-size:14px}
+.cookie .actions{display:flex; gap:10px; flex-wrap:wrap; justify-content:flex-end}
+
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
+
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns: 1fr}
+  .feature-grid{grid-template-columns: 1fr}
+  .two-col{grid-template-columns: 1fr}
+  .items{grid-template-columns: repeat(2, minmax(0, 1fr))}
+  .tier-grid{grid-template-columns: 1fr}
+  .locator{grid-template-columns: 1fr}
+  .map{min-height:360px}
+}
+
+@media (max-width: 720px){
+  .h1{font-size:36px}
+  .h2{font-size:28px}
+  .nav-links{display:none}
+  .nav-actions{display:none}
+  .mobile-toggle{display:inline-flex}
+  .mobile-drawer{
+    position:fixed;
+    inset:64px 14px auto 14px;
+    background:rgba(255,255,255,0.98);
+    border:1px solid rgba(20,32,21,0.14);
+    border-radius:18px;
+    box-shadow:var(--shadow);
+    padding:10px;
+    z-index:1500;
+  }
+  .mobile-drawer[hidden]{display:none}
+  .mobile-drawer a{display:block; padding:12px 12px; border-radius:14px; font-weight:750; color:var(--forest)}
+  .mobile-drawer a:hover{background:rgba(0,130,74,0.08)}
+
+  .footer-grid{grid-template-columns: 1fr}
+  .footer-section{border-color:rgba(20,32,21,0.10); background:rgba(255,255,255,0.65)}
